import json, re, pathlib
ROOT = pathlib.Path("/tmp/verifyB3-M4-d")
out = (ROOT / "ledgers/M4/scripts/M4-d-r3/mutate_r3.out").read_text().splitlines()
mutants = []
for line in out:
    m = re.match(r"(KILLED|SURVIVED) (\S+?): (.*) -> (.*)$", line)
    if not m:
        continue
    status, name, desc, killed = m.groups()
    entry = {"id": name.removesuffix(".py"), "description": desc}
    if status == "KILLED":
        entry["killed_by"] = killed
    else:
        entry["killed_by"] = None
        entry["survived"] = True
    mutants.append(entry)
